    assets = load_assets(ws)
    ruled = _rulings_by_case(ws)
    differences, resolved, steps = [], [], 0
    for case in sorted((c for c in assets["cases"] if "_load_error" not in c), key=lambda c: c["id"]):
        cid = case["id"]
