        symbols = ((masks.get("units") or {}).get(cid) or {}).get("symbols", {})
        types = {s: info.get("type") for s, info in symbols.items()}
        values = {s: info["value"] for s, info in symbols.items() if "value" in info}
        for step in case["steps"]:
            name = step["name"]
